description:
Write `fn tokenize(src: &str) -> Result<Vec<Tok>, String>` for small arithmetic, where:

```rust
#[derive(Debug, Clone, PartialEq)]
enum Tok { Num(f64), Ident(String), Op(char), LParen, RParen }
```

- numbers are digits with at most one `.` (like `3`, `2.5`, `.5`); a second `.` in a number is an error;
- names start with a letter or `_` and continue with letters, digits or `_`;
- operators are `+ - * / ^`; spaces are skipped;
- any other character gives `Err("unexpected 'c' at column N")`, with columns counted from 1 in characters.

starter.solution.rs:
#[derive(Debug, Clone, PartialEq)]
enum Tok {
    Num(f64),
    Ident(String),
    Op(char),
    LParen,
    RParen,
}

fn tokenize(src: &str) -> Result<Vec<Tok>, String> {
    Ok(src.split_whitespace().map(|w| Tok::Ident(w.to_string())).collect())
}

solution.solution.rs:
#[derive(Debug, Clone, PartialEq)]
enum Tok {
    Num(f64),
    Ident(String),
    Op(char),
    LParen,
    RParen,
}

fn tokenize(src: &str) -> Result<Vec<Tok>, String> {
    let chars: Vec<char> = src.chars().collect();
    let mut out = Vec::new();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c.is_whitespace() {
            i += 1;
        } else if c.is_ascii_digit() || c == '.' {
            let start = i;
            let mut dots = 0;
            while i < chars.len() && (chars[i].is_ascii_digit() || chars[i] == '.') {
                if chars[i] == '.' {
                    dots += 1;
                    if dots > 1 {
                        return Err(format!("unexpected '.' at column {}", i + 1));
                    }
                }
                i += 1;
            }
            let text: String = chars[start..i].iter().collect();
            let n = text.parse::<f64>().map_err(|_| format!("bad number at column {}", start + 1))?;
            out.push(Tok::Num(n));
        } else if c.is_alphabetic() || c == '_' {
            let start = i;
            while i < chars.len() && (chars[i].is_alphanumeric() || chars[i] == '_') {
                i += 1;
            }
            out.push(Tok::Ident(chars[start..i].iter().collect()));
        } else {
            out.push(match c {
                '+' | '-' | '*' | '/' | '^' => Tok::Op(c),
                '(' => Tok::LParen,
                ')' => Tok::RParen,
                _ => return Err(format!("unexpected '{c}' at column {}", i + 1)),
            });
            i += 1;
        }
    }
    Ok(out)
}

unitTests:
use Tok::*;

test("numbers, names and symbols", || {
    check_eq(tokenize("2 * (x_1 + 1.5)"), Ok(vec![Num(2.0), Op('*'), LParen, Ident("x_1".into()), Op('+'), Num(1.5), RParen]));
    check_eq(tokenize(".5^y"), Ok(vec![Num(0.5), Op('^'), Ident("y".into())]));
    check_eq(tokenize("   "), Ok(vec![]));
});

test("errors give the column", || {
    check_eq(tokenize("3 $ 4"), Err("unexpected '$' at column 3".to_string()));
    check_eq(tokenize("1.2.3"), Err("unexpected '.' at column 4".to_string()));
    check_eq(tokenize("é + %"), Err("unexpected '%' at column 5".to_string()));
});

